import React, { useEffect, useRef, useState } from "react";

const LEAFLET_CSS_ID = "leaflet-css";
const LEAFLET_SCRIPT_ID = "leaflet-script";
const LEAFLET_CSS_URL = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.css";
const LEAFLET_SCRIPT_URL = "https://unpkg.com/leaflet@1.9.4/dist/leaflet.js";

let leafletLoaderPromise = null;

function ensureLeaflet() {
  if (window.L) {
    return Promise.resolve(window.L);
  }

  if (!leafletLoaderPromise) {
    leafletLoaderPromise = new Promise((resolve, reject) => {
      if (!document.getElementById(LEAFLET_CSS_ID)) {
        const link = document.createElement("link");
        link.id = LEAFLET_CSS_ID;
        link.rel = "stylesheet";
        link.href = LEAFLET_CSS_URL;
        document.head.appendChild(link);
      }

      const existingScript = document.getElementById(LEAFLET_SCRIPT_ID);
      if (existingScript) {
        existingScript.addEventListener("load", () => resolve(window.L), {
          once: true,
        });
        existingScript.addEventListener(
          "error",
          () => reject(new Error("Leaflet failed to load")),
          { once: true }
        );
        return;
      }

      const script = document.createElement("script");
      script.id = LEAFLET_SCRIPT_ID;
      script.src = LEAFLET_SCRIPT_URL;
      script.async = true;
      script.onload = () => resolve(window.L);
      script.onerror = () => reject(new Error("Leaflet failed to load"));
      document.body.appendChild(script);
    });
  }

  return leafletLoaderPromise;
}

function generateTimeSteps() {
  const steps = [];
  const alignedNow = new Date();
  alignedNow.setUTCSeconds(0, 0);
  alignedNow.setUTCMinutes(Math.floor(alignedNow.getUTCMinutes() / 10) * 10);

  for (let index = 6; index >= 0; index -= 1) {
    const step = new Date(alignedNow.getTime() - index * 10 * 60 * 1000);
    steps.push(step.toISOString().split(".")[0]);
  }

  return steps;
}

function formatRadarTime(timeString) {
  const value = new Date(`${timeString}Z`);
  return value.toLocaleString("en-GB", {
    day: "2-digit",
    month: "short",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function buildRadarTileUrl(time) {
  return `/weather/radar-tile/{z}/{x}/{y}.webp?time=${encodeURIComponent(time)}`;
}

export default function RadarMap({ weather }) {
  const mapElementRef = useRef(null);
  const mapRef = useRef(null);
  const layersRef = useRef([]);
  const timeStepsRef = useRef([]);
  const intervalRef = useRef(null);
  const frameIndexRef = useRef(0);

  const [isAnimating, setIsAnimating] = useState(false);
  const [statusText, setStatusText] = useState("Loading radar...");
  const [mapError, setMapError] = useState("");

  useEffect(() => {
    return () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
      }

      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
      }
    };
  }, []);

  useEffect(() => {
    if (!weather?.radar_enabled) {
      setIsAnimating(false);
      setMapError("");
      setStatusText("Radar unavailable");
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
      return undefined;
    }

    let cancelled = false;

    const stopAnimation = () => {
      if (intervalRef.current) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
      setIsAnimating(false);
    };

    const clearRadarLayers = () => {
      layersRef.current.forEach((layer) => layer.remove());
      layersRef.current = [];
      frameIndexRef.current = 0;
    };

    async function setupMap() {
      try {
        const L = await ensureLeaflet();
        if (cancelled || !mapElementRef.current) {
          return;
        }

        let map = mapRef.current;
        if (!map) {
          map = L.map(mapElementRef.current, {
            zoomControl: true,
            attributionControl: true,
          });
          L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
            attribution: "&copy; OpenStreetMap contributors",
          }).addTo(map);
          mapRef.current = map;
        }

        map.setView([weather.latitude, weather.longitude], 6);
        stopAnimation();
        clearRadarLayers();

        const timeSteps = generateTimeSteps();
        timeStepsRef.current = timeSteps;

        timeSteps.forEach((time, index) => {
          const layer = L.tileLayer(buildRadarTileUrl(time), {
            opacity: index === 0 ? 0.72 : 0,
            zIndex: 120,
          }).addTo(map);
          layersRef.current.push(layer);
        });

        setMapError("");
        setStatusText(`Frame: ${formatRadarTime(timeSteps[0])}`);
        window.setTimeout(() => {
          if (!cancelled && mapRef.current) {
            mapRef.current.invalidateSize();
          }
        }, 0);
      } catch (error) {
        if (!cancelled) {
          setMapError("Unable to load the radar map right now.");
        }
      }
    }

    setupMap();

    return () => {
      cancelled = true;
      stopAnimation();
      clearRadarLayers();
    };
  }, [weather]);

  const nextFrame = () => {
    const layers = layersRef.current;
    const timeSteps = timeStepsRef.current;
    if (!layers.length || !timeSteps.length) {
      return;
    }

    layers[frameIndexRef.current].setOpacity(0);
    frameIndexRef.current = (frameIndexRef.current + 1) % layers.length;
    layers[frameIndexRef.current].setOpacity(0.72);
    setStatusText(`Frame: ${formatRadarTime(timeSteps[frameIndexRef.current])}`);
  };

  const toggleAnimation = () => {
    if (!layersRef.current.length) {
      return;
    }

    if (intervalRef.current) {
      clearInterval(intervalRef.current);
      intervalRef.current = null;
      setIsAnimating(false);
      return;
    }

    intervalRef.current = window.setInterval(nextFrame, 800);
    setIsAnimating(true);
  };

  if (!weather) {
    return null;
  }

  return (
    <div className="glass-card radar-card">
      <div className="radar-header">
        <div>
          <h2 className="section-title radar-title">Radar Animation</h2>
          <p className="radar-subtitle">
            Visual Crossing precipitation composite centered on {weather.city}
          </p>
        </div>

        <div className="radar-controls">
          <button
            className="radar-toggle"
            type="button"
            onClick={toggleAnimation}
            disabled={!weather.radar_enabled || Boolean(mapError)}
          >
            {isAnimating ? "Stop animation" : "Start animation"}
          </button>
          <span className="radar-time">{statusText}</span>
        </div>
      </div>

      {!weather.radar_enabled ? (
        <div className="radar-empty">
          Add `VISUAL_CROSSING_API_KEY=...` to the project `.env`, restart the
          backend, and the radar layer will appear here.
        </div>
      ) : mapError ? (
        <div className="radar-empty">{mapError}</div>
      ) : (
        <>
          <div className="map-shell">
            <div ref={mapElementRef} className="weather-map" />
          </div>
          <p className="radar-note">
            Uses OpenStreetMap for the basemap and Visual Crossing radar tiles
            for the animated precipitation overlay.
          </p>
        </>
      )}
    </div>
  );
}
